// Vulkan engine state is created lazily on first context creation.
var g_ctx: vk.Ctx = .{};
var g_vk_ready: bool = false;

const Context = struct {
    model: *Model,
    n_ctx: i32,
    pos: i32 = 0,
    failed: bool = false,
};

export fn bonsai_context_create(
    model: ?*ModelOpaque,
    n_ctx: i32,
    n_batch: i32,
    out_ctx: ?*?*ContextOpaque,
) callconv(.c) i32 {
    _ = n_batch;
    if (out_ctx) |p| p.* = null;
    if (model == null or out_ctx == null) {
        setErr("invalid argument", .{});
        return -1;
    }
    if (n_ctx < 1 or n_ctx > 16384) {
        setErr("invalid n_ctx: {d}", .{n_ctx});
        return -1;
    }
    const m: *Model = @ptrCast(@alignCast(model.?));
    if (!g_vk_ready) {
        vk.init(&g_ctx) catch |e| {
            setErr("Vulkan initialisation failed: {s}", .{@errorName(e)});
            return -5;
        };
        g_vk_ready = true;
    }
    const c = alloc.create(Context) catch return -2;
    c.* = .{ .model = m, .n_ctx = n_ctx };
    out_ctx.?.* = @ptrCast(c);
    return 0;

