#version 450
layout(local_size_x = 256) in;
layout(std430, binding = 0) readonly buffer XB { float x[]; };
layout(std430, binding = 1) readonly buffer WB { float w[]; };
layout(std430, binding = 2) writeonly buffer YB { float y[]; };
layout(push_constant) uniform PC { uint n; float eps; uint w_off; uint flags; } pc;

shared float red[256];

void main() {
    uint tid = gl_LocalInvocationID.x;
    uint row = gl_WorkGroupID.x;
    uint base = row * pc.n;
    float sum = 0.0;
    for (uint i = tid; i < pc.n; i += 256u) { float v = x[base + i]; sum += v * v; }
    red[tid] = sum;
    barrier();
    for (uint s = 128u; s > 0u; s >>= 1) {
        if (tid < s) red[tid] += red[tid + s];
        barrier();
    }
    float rms = sqrt(red[0] / float(pc.n) + pc.eps);
    for (uint i = tid; i < pc.n; i += 256u) {
        float v = x[base + i] / rms;
        if (pc.flags != 0u) v *= w[pc.w_off + i];
        y[base + i] = v;
    }
}
====
#version 450
layout(local_size_x = 64) in;
layout(std430, binding = 0) readonly buffer XB { float x[]; };
layout(std430, binding = 1) writeonly buffer YB { float y[]; };
layout(push_constant) uniform PC { uint pos; uint nheads; } pc;

void main() {
    uint h = gl_WorkGroupID.x;
    uint i = gl_LocalInvocationID.x;
    uint base = h * 256u;
    if (i < 32u) {
        float ang = float(pc.pos) * pow(10000000.0, -float(i) / 32.0);
        float c = cos(ang); float s = sin(ang);
        float a = x[base + i];
        float b = x[base + i + 32u];
        y[base + i] = a * c - b * s;
    } else {
        uint j = i - 32u;
        float ang = float(pc.pos) * pow(10000000.0, -float(j) / 32.0);
        float c = cos(ang); float s = sin(ang);
        float a = x[base + j];
        float b = x[base + i];
        y[base + i] = a * s + b * c;
    }
    y[base + 64u + i] = x[base + 64u + i];
    y[base + 128u + i] = x[base + 128u + i];
    y[base + 192u + i] = x[base + 192u + i];
}
====
#version 450
layout(local_size_x = 256) in;
layout(std430, binding = 0) readonly buffer AB { float a[]; };
layout(std430, binding = 1) readonly buffer BB { float b[]; };
layout(std430, binding = 2) writeonly buffer YB { float y[]; };
layout(push_constant) uniform PC { uint n; uint op; } pc;

void main() {
    uint i = gl_WorkGroupID.x * 256u + gl_LocalInvocationID.x;
    if (i >= pc.n) return;
    float x = a[i];
    float z = b[i];
    if (pc.op == 0u) y[i] = x + z;
    else if (pc.op == 1u) y[i] = (x / (1.0 + exp(-x))) * z;
    else if (pc.op == 2u) y[i] = x / (1.0 + exp(-z));
    else y[i] = x * z;
}

