import unicodedata, sys

def cat_of(ch):
    c = unicodedata.category(ch)
    if c[0] == 'L': return 1
    if c[0] == 'M': return 2
    if c[0] == 'N': return 3
    return 0

ranges = []
cur = None
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF:
        c = 0
    else:
        c = cat_of(chr(cp))
    if c == 0:
        if cur: ranges.append(cur); cur = None
    else:
        if cur and cur[2] == c and cur[1] == cp - 1:
            cur = (cur[0], cp, c)
        else:
            if cur: ranges.append(cur)
