                    const ck = Dec.cp(text, k);
                    if (isL(ck) or isM(ck)) {
                        k += Dec.len(text, k);
                        while (k < text.len) {
                            const cc = Dec.cp(text, k);
                            if (!(isL(cc) or isM(cc))) break;
                            k += Dec.len(text, k);
                        }
                        j = k;
                        matched = true;
                    }
                }
                // alt3: single number
                if (!matched) {
                    const ck = Dec.cp(text, start);
                    if (isN(ck)) {
                        j = start + Dec.len(text, start);
                        matched = true;
                    }
                }
                // alt4: ' '? [^ \s L M N]+ [\r\n]*
