                    var m = start;
                    const c0b = Dec.cp(text, m);
                    if (c0b == ' ') m += Dec.len(text, m);
                    var any = false;
                    while (m < text.len) {
                        const cc = Dec.cp(text, m);
                        if (isS(cc) or isL(cc) or isM(cc) or isN(cc)) break;
                        m += Dec.len(text, m);
                        any = true;
                    }
                    if (any) {
                        while (m < text.len) {
                            const cc = Dec.cp(text, m);
                            if (cc != '\r' and cc != '\n') break;
                            m += Dec.len(text, m);
                        }
                        j = m;
                        matched = true;
                    }
                }
                // alt5: \s*[\r\n]+
                if (!matched) {
                    var m = start;
                    while (m < text.len) {
                        const cc = Dec.cp(text, m);
                        if (!isS(cc)) break;
                        m += Dec.len(text, m);
